package com.cookly.modelos;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="usuarios") public class Usuario { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String correo; @Column(nullable=false) private String contrasena; @Column(nullable=false) private String nombre; @Enumerated(EnumType.STRING) @Column(nullable=false) private Rol rol=Rol.USUARIO; private boolean activo=true; private Instant creadoEn=Instant.now(); public Long getId(){return id;} public String getCorreo(){return correo;} public String getContrasena(){return contrasena;} public String getNombre(){return nombre;} public Rol getRol(){return rol;} public boolean isActivo(){return activo;} public Instant getCreadoEn(){return creadoEn;} public void setCorreo(String v){correo=v;} public void setContrasena(String v){contrasena=v;} public void setNombre(String v){nombre=v;} public void setRol(Rol v){rol=v;} }
